# SPDX-License-Identifier: MIT
# The board's connector as machine sees it, and the hardware behind it, from the board's
# description (mpy_board): Pin on Linux GPIO lines; ADC, PWM, I2C, SPI and UART on the Cortex-M4
# where there is one (mpy_m4), on Linux's drivers elsewhere. In the LVGL MPY Studio simulator there
# is no hardware: a stand-in gives changing values on the STM32MP157C-DK2's Arduino connector, so
# the screen can be tried without a board.

import time

try:
    import machine
    import mpy_board
    import mpy_m4

    HARDWARE = hasattr(machine, "PWM") or hasattr(machine, "ADC")
    MCU = mpy_m4.available()
except ImportError:
    machine = mpy_board = mpy_m4 = None
    HARDWARE = False
    MCU = True

# The simulator's connector: label, MCU pin, kind (gpio, adc, pwm, i2c, spi, uart) and its bus.
SIMULATED = [
    ("D0", "PE7", "uart", "7"), ("D1", "PE8", "uart", "7"), ("D2", "PE1", "gpio", None),
    ("D3", "PD14", "gpio", None), ("D4", "PE10", "gpio", None), ("D5", "PD15", "gpio", None),
    ("D6", "PE9", "pwm", None), ("D7", "PD1", "gpio", None), ("D8", "PG3", "gpio", None),
    ("D9", "PH6", "gpio", None), ("D10", "PE11", "gpio", None), ("D11", "PE14", "spi", "4"),
    ("D12", "PE13", "spi", "4"), ("D13", "PE12", "spi", "4"), ("D14", "PA12", "i2c", "5"),
    ("D15", "PA11", "i2c", "5"), ("A0", "ANA0", "adc", None), ("A1", "ANA1", "adc", None),
    ("A2", "PF14", "adc", None), ("A3", "PF13", "adc", None), ("A4", "PC3", "adc", None),
    ("A5", "PF12", "adc", None),
]
# The same for a small screen in the simulator: the STM32MP135F-DK's 40-pin connector CN8, as its
# description makes it, on Linux's drivers.
SIMULATED_CN8 = [
    ("3", "PH6", "i2c", "5"), ("5", "PD1", "i2c", "5"), ("7", "PB1", "pwm", None), ("8", "PC0", "adc", None),
    ("10", "PB0", "adc", None), ("11", "PC2", "gpio", None), ("12", "PA4", "gpio", None),
    ("13", "PC3", "adc", None), ("15", "PF13", "adc", None), ("16", "PG1", "gpio", None),
    ("18", "PG3", "gpio", None), ("19", "PH3", "spi", "5"), ("21", "PA8", "spi", "5"), ("22", "PI0", "gpio", None),
    ("23", "PH7", "spi", "5"), ("24", "PH11", "spi", "5"), ("26", "PF10", "gpio", None), ("27", "PE8", "i2c", "1"),
    ("28", "PD12", "i2c", "1"), ("29", "PE6", "gpio", None), ("31", "PD13", "pwm", None), ("32", "PE5", "pwm", None),
    ("33", "PF9", "uart", "8"), ("35", "PF11", "gpio", None), ("36", "PA7", "gpio", None), ("37", "PE1", "uart", "8"),
    ("38", "PA5", "gpio", None), ("40", "PA0", "gpio", None),
]
POWER = ("3V3", "5V", "GND", "VIN", "IOREF", "RESET", "AREF", "NC")
LED_SLOTS = ("red", "orange", "blue")  # the screen's three LED switches
LED_ORDER = ("red", "green", "orange", "blue")


def _sort_key(label):
    return (0, int(label)) if label.isdigit() else (1, label[0], int(label[1:]) if label[1:].isdigit() else 0)


def _connector():
    # [(label, MCU pin, kind, bus)] of the connector's signal pins, the kind from what uses each.
    described = mpy_board.describe()
    found = described.get("connector", {}).get("pins", {})
    adc = described.get("adc", {}).get("pins", [])
    pins = []
    for label in sorted(found, key=_sort_key):
        mcu = found[label]
        if mcu in POWER:
            continue
        kind, bus = "gpio", None
        if mcu in adc:
            kind = "adc"
        elif mcu in described.get("pwm", {}):
            kind = "pwm"
        for key in ("i2c", "spi", "uart"):
            for number, entry in described.get(key, {}).items():
                roles = [role for role in ("scl", "sda", "sck", "mosi", "miso", "tx", "rx") if entry.get(role) == mcu]
                if roles or (entry.get("cs") == mcu and entry.get("cs_kernel")):
                    kind, bus = key, number
        pins.append((label, mcu, kind, bus))
    return pins


PINS = _connector() if HARDWARE else SIMULATED
ARDUINO = all(label[0] in "DA" and label[1:].isdigit() for label, mcu, kind, bus in PINS)
CONNECTOR = mpy_board.describe().get("connector", {}).get("name", "") if HARDWARE else "Arduino"
RANGE_UV = mpy_board.describe().get("adc", {}).get("range_uv", 2500000) if HARDWARE else (2500000 if MCU else 3300000)
SERVED = "the Cortex-M4" if MCU else "Linux's drivers"


def describe(label, short=False):
    # A line about a pin, for the screen (short: a few words, for a small one).
    for name, mcu, kind, bus in PINS:
        if name == label:
            break
    else:
        return ""
    served = "" if short else " on " + SERVED
    if kind == "gpio":
        return "machine.Pin" if short else "A Linux GPIO line: machine.Pin"
    if kind == "adc":
        if short:
            return "machine.ADC, 0-%.1f V" % (RANGE_UV / 1e6)
        return "Analog input, 0 to %.1f V: machine.ADC%s" % (RANGE_UV / 1e6, served)
    if kind == "pwm":
        entry = mpy_board.describe().get("pwm", {}).get(mcu, {}) if HARDWARE else {"name": "TIM1 channel 1" if MCU else "PWM"}
        return "%s: machine.PWM%s" % (entry.get("name", "PWM"), served)
    return "machine.%s(%s)%s" % (kind.upper(), bus, served)


def firmware():
    if not HARDWARE:
        return "simulator: values are made up"
    if not MCU:
        return "machine on Linux's drivers"
    try:
        return mpy_m4.info()
    except OSError as error:
        return "Cortex-M4: %s" % error


class _Led:
    # One LED of the description: a GPIO line (by name, or ["chip", line]), the Cortex-M4's, or
    # Linux's LED class.
    def __init__(self, name, spec):
        self.name = name
        self.spec = spec
        self._pin = None

    def how(self):
        if "pin" in self.spec:
            return "machine.Pin"
        return "Cortex-M4" if self.spec.get("mcu") else "Linux LED class"

    def set(self, on):
        spec = self.spec
        if "pin" in spec:
            if self._pin is None:
                line = tuple(spec["pin"]) if isinstance(spec["pin"], list) else spec["pin"]
                self._pin = machine.Pin(line, machine.Pin.OUT, value=1 if spec.get("active_low") else 0)
            self._pin.value((0 if on else 1) if spec.get("active_low") else (1 if on else 0))
        elif spec.get("mcu"):
            mpy_m4.led(on)
        elif "sysfs" in spec:
            # On is steady, off gives the LED back to its trigger (the kernel's heartbeat).
            root = "/sys/class/leds/%s/" % spec["sysfs"]
            with open(root + "trigger", "w") as f:
                f.write("none" if on else "heartbeat")
            if on:
                with open(root + "brightness", "w") as f:
                    f.write("1")


def leds():
    # {screen slot: _Led}: each LED of the board on a switch, its own colour's where there is one.
    found = mpy_board.describe().get("leds", {}) if HARDWARE else {}
    free = [name for name in LED_ORDER if name in found and name not in LED_SLOTS]
    chosen = {}
    for slot in LED_SLOTS:
        if slot in found:
            chosen[slot] = _Led(slot, found[slot])
    for slot in LED_SLOTS:
        if slot not in chosen and free:
            name = free.pop(0)
            chosen[slot] = _Led(name, found[name])
    return chosen


class Hardware:
    # What the screen asks of the board; the same calls in the simulator's stand-in below.

    def __init__(self):
        self._pins = {}  # MCU pin -> (machine.Pin, "in" or "out")
        self._pwms = {}
        self._adcs = {}
        self.leds = leds()

    def release(self, pin):
        old = self._pins.pop(pin, None)
        if old is not None:
            old[0].deinit()
        pwm = self._pwms.pop(pin, None)
        if pwm is not None:
            pwm.deinit()

    def pin_in(self, pin, pull_up):
        self.release(pin)
        pull = machine.Pin.PULL_UP if pull_up else None
        self._pins[pin] = (machine.Pin(pin, machine.Pin.IN, pull), "in")

    def pin_out(self, pin, value):
        if pin in self._pins and self._pins[pin][1] == "out":
            self._pins[pin][0].value(value)
            return
        self.release(pin)
        self._pins[pin] = (machine.Pin(pin, machine.Pin.OUT, value=value), "out")

    def pin_value(self, pin):
        return self._pins[pin][0].value()

    def seen_by_m4(self, pin):
        # The level the Cortex-M4 reads on the pin, whoever drives it; None without one.
        if not MCU:
            return None
        frequency, high = mpy_m4.measure(pin, 2)
        return 1 if high > 0.5 else 0

    def adc_uv(self, pin):
        if pin not in self._adcs:
            self._adcs[pin] = machine.ADC(pin)
        return self._adcs[pin].read_uv()

    def pwm(self, pin, frequency, percent):
        duty = percent * 65535 // 100
        if pin not in self._pwms:
            self._pwms[pin] = machine.PWM(pin, freq=frequency, duty_u16=duty)
        else:
            self._pwms[pin].init(freq=frequency, duty_u16=duty)

    def measure(self, pin, frequency):
        # A few periods of the signal, at least 10 ms; None without a Cortex-M4 to measure it.
        if not MCU:
            return None
        return mpy_m4.measure(pin, max(10, min(1000, 3000 // frequency + 1)))

    def scan(self, bus):
        return machine.I2C(int(bus)).scan()

    def led(self, slot, on):
        self.leds[slot].set(on)


class _SimulatedLed:
    def __init__(self, name, where, how):
        self.name = name
        self.spec = {"where": where}
        self._how = how

    def how(self):
        return self._how


class Simulated:
    # The simulator's stand-in: an output reads back what was set, inputs and ADCs change slowly.

    def __init__(self):
        self._out = {}
        self._pwm = (1000, 25)
        if MCU:
            self.leds = {"red": _SimulatedLed("red", "PA13", "machine.Pin"),
                         "orange": _SimulatedLed("orange", "PH7", "Cortex-M4"),
                         "blue": _SimulatedLed("blue", "PD11", "Linux LED class")}
        else:
            self.leds = {"red": _SimulatedLed("green", "LD7", "machine.Pin"),
                         "orange": _SimulatedLed("orange", "LD6", "machine.Pin")}

    def release(self, pin):
        self._out.pop(pin, None)

    def pin_in(self, pin, pull_up):
        self._out.pop(pin, None)

    def pin_out(self, pin, value):
        self._out[pin] = value

    def pin_value(self, pin):
        if pin in self._out:
            return self._out[pin]
        return (time.ticks_ms() // 1000 + len(pin)) % 2

    def adc_uv(self, pin):
        phase = (time.ticks_ms() // 50 + 37 * len(pin) + ord(pin[-1])) % 200
        return 400000 + abs(phase - 100) * 15000

    def pwm(self, pin, frequency, percent):
        self._pwm = (frequency, percent)

    def seen_by_m4(self, pin):
        return self.pin_value(pin) if MCU else None

    def measure(self, pin, frequency):
        if not MCU:
            return None
        return float(self._pwm[0]), self._pwm[1] / 100

    def scan(self, bus):
        return [0x3C, 0x76] if MCU else [0x14, 0x5D]

    def led(self, slot, on):
        pass


hardware = Hardware() if HARDWARE else Simulated()


def simulate_small():
    # In the simulator, on a small screen: the STM32MP135F-DK's story, its connector CN8 on Linux's
    # drivers, no microcontroller. Called once the screen exists.
    global PINS, ARDUINO, CONNECTOR, RANGE_UV, MCU, SERVED, hardware
    if HARDWARE:
        return
    MCU = False
    PINS = SIMULATED_CN8
    ARDUINO = False
    CONNECTOR = "CN8"
    RANGE_UV = 3300000
    SERVED = "Linux's drivers"
    hardware = Simulated()
